/**
 * The service worker.
 *
 * Two jobs, and deliberately only two: make the portal installable to a home
 * screen, and make it open instantly rather than refetching the shell every
 * time. It does NOT make the app work offline — reading and writing data
 * still needs Supabase, and a write queue that survives being offline is a
 * different and much larger project. Better to be honest about that than to
 * ship a shell that opens to an empty room and looks broken.
 *
 * Hand-written rather than generated by vite-plugin-pwa: the whole thing is
 * sixty lines, this project adds no dependency it can avoid, and a generated
 * worker is the last place anyone wants a surprise on a rolldown upgrade.
 *
 * Cache invalidation is mostly handled for us. Vite fingerprints every built
 * asset (`index-BAdIwwjG.js`), so a new build asks for new filenames and the
 * old entries simply stop being requested; CACHE is bumped only when the
 * logic in this file changes, and activate then clears anything older.
 */
const CACHE = 'anvik-v1';

self.addEventListener('install', (event) => {
  // The new worker should take over on the next navigation, not the next
  // browser restart — otherwise a fix can sit unused for days.
  self.skipWaiting();
  event.waitUntil(caches.open(CACHE));
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    (async () => {
      const names = await caches.keys();
      await Promise.all(names.filter((name) => name !== CACHE).map((name) => caches.delete(name)));
      await self.clients.claim();
    })(),
  );
});

self.addEventListener('fetch', (event) => {
  const request = event.request;
  // Same-origin GETs only. Supabase, Google and the font CDNs must never be
  // touched: caching an API response here would serve stale data with no way
  // to tell, and caching an authenticated one would be worse.
  if (request.method !== 'GET') return;
  const url = new URL(request.url);
  if (url.origin !== self.location.origin) return;

  // Navigations: network first, so a deploy is picked up immediately, with
  // the cached shell as the fallback when the network is slow or gone.
  if (request.mode === 'navigate') {
    event.respondWith(
      (async () => {
        try {
          const fresh = await fetch(request);
          const cache = await caches.open(CACHE);
          cache.put('/index.html', fresh.clone());
          return fresh;
        } catch {
          const cached = await caches.match('/index.html');
          return cached ?? Response.error();
        }
      })(),
    );
    return;
  }

  // Fingerprinted build output: cache first. The filename changes whenever
  // the contents do, so a hit is always correct.
  if (url.pathname.startsWith('/assets/') || url.pathname.startsWith('/icons/')) {
    event.respondWith(
      (async () => {
        const cached = await caches.match(request);
        if (cached) return cached;
        const fresh = await fetch(request);
        if (fresh.ok) {
          const cache = await caches.open(CACHE);
          cache.put(request, fresh.clone());
        }
        return fresh;
      })(),
    );
  }
});
